import os, pty, time, select, signal

# Drive test_pty.py under a real controlling PTY and send a Ctrl-C (0x03),
# exactly like a keyboard interrupt from a terminal.
pid, fd = pty.fork()
if pid == 0:
    os.environ["PYTHONPATH"] = "/app"
    os.execvp("python3", ["python3", "-u", "/tmp/opencode/test_pty.py"])
else:
    buf = b""
    start = time.time()
    sent = False
    while True:
        r, _, _ = select.select([fd], [], [], 0.2)
        if r:
            try:
                data = os.read(fd, 1024)
            except OSError:
                break
            if not data:
                break
            buf += data
        # After 2s, send Ctrl-C (ETX) to the terminal
        if not sent and time.time() - start > 2:
            os.write(fd, b"\x03")
            sent = True
        if time.time() - start > 15:
            break
    try:
        os.close(fd)
    except OSError:
        pass
    os.waitpid(pid, 0)
    print("=== CAPTURED OUTPUT ===")
    print(buf.decode(errors="replace"))
